namespace SmartParking.Domain.Common;

/// <summary>
/// Root of a consistency boundary. Collects the domain events raised by a change; the unit of work dequeues them on
/// save and writes one outbox message per event and one audit entry per entity the event changed (spec 001,
/// spec 002, ADR 0006). By default the only changed entity is the root itself.
/// </summary>
public abstract class AggregateRoot
{
    private readonly List<RaisedEvent> raisedEvents = [];

    /// <summary>UUID v7, generated by the application from the injected <c>TimeProvider</c>.</summary>
    public Guid Id { get; protected init; }

    public IReadOnlyCollection<IDomainEvent> DomainEvents => [.. raisedEvents.Select(raised => raised.Event)];

    /// <summary>Returns the pending events and clears them, so a second save does not repeat them.</summary>
    public IReadOnlyList<IDomainEvent> DequeueDomainEvents() =>
        [.. DequeueRaisedEvents().Select(raised => raised.Event)];

    /// <summary>Returns the pending events with the entities each one changed, and clears them.</summary>
    public IReadOnlyList<RaisedEvent> DequeueRaisedEvents()
    {
        RaisedEvent[] pending = [.. raisedEvents];
        raisedEvents.Clear();
        return pending;
    }

    /// <summary>
    /// Records <paramref name="domainEvent"/>. <paramref name="changed"/> lists the entities this transition changed
    /// (each gets one audit entry); when empty, the root itself is the only changed entity.
    /// </summary>
    protected void Raise(IDomainEvent domainEvent, params ReadOnlySpan<object> changed)
    {
        ArgumentNullException.ThrowIfNull(domainEvent);

        object[] entities = changed.IsEmpty ? [this] : [.. changed];
        foreach (var entity in entities)
        {
            ArgumentNullException.ThrowIfNull(entity, nameof(changed));
        }

        raisedEvents.Add(new RaisedEvent(domainEvent, entities));
    }
}
